#ifndef HB_OPEN_FILE_HH
#define HB_OPEN_FILE_HH

#include "hb-open-type.hh"
#include "hb-ot-head-table.hh"


namespace OT {


/*
 *
 * The OpenType Font File
 *
 */


/*
 * Organization of an OpenType Font
 */

struct OpenTypeFontFile;
struct OffsetTable;
struct TTCHeader;


typedef struct TableRecord
{
  int cmp (Tag t) const
  { return -t.cmp (tag); }

  static int cmp (const void *pa, const void *pb)
  {
    const TableRecord *a = (const TableRecord *) pa;
    const TableRecord *b = (const TableRecord *) pb;
    return b->cmp (a->tag);
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this));
  }

  Tag           tag;            /* 4-byte identifier. */
  CheckSum      checkSum;       /* CheckSum for this table. */
  Offset32      offset;         /* Offset from beginning of TrueType font
                                 * file. */
  HBUINT32      length;         /* Length of this table. */
  public:
  DEFINE_SIZE_STATIC (16);
} OpenTypeTable;

typedef struct OffsetTable
{
  friend struct OpenTypeFontFile;

  inline unsigned int get_table_count (void) const
  { return tables.len; }
  inline const TableRecord& get_table (unsigned int i) const
  {
    return tables[i];
  }
  inline unsigned int get_table_tags (unsigned int  start_offset,
                                      unsigned int *table_count, /* IN/OUT */
                                      hb_tag_t     *table_tags /* OUT */) const
  {
    if (table_count)
    {
      if (start_offset >= tables.len)
        *table_count = 0;
      else
        *table_count = MIN<unsigned int> (*table_count, tables.len - start_offset);

      const TableRecord *sub_tables = tables.arrayZ + start_offset;
      unsigned int count = *table_count;
      for (unsigned int i = 0; i < count; i++)
        table_tags[i] = sub_tables[i].tag;
    }
    return tables.len;
  }
  inline bool find_table_index (hb_tag_t tag, unsigned int *table_index) const
  {
    Tag t;
    t.set (tag);
    /* Linear-search for small tables to work around fonts with unsorted
     * table list. */
    int i = tables.len < 64 ? tables.lsearch (t) : tables.bsearch (t);
    if (table_index)
      *table_index = i == -1 ? (unsigned) Index::NOT_FOUND_INDEX : (unsigned) i;
    return i != -1;
  }
  inline const TableRecord& get_table_by_tag (hb_tag_t tag) const
  {
    unsigned int table_index;
    find_table_index (tag, &table_index);
    return get_table (table_index);
  }

  public:

  inline bool serialize (hb_serialize_context_t *c,
                         hb_tag_t sfnt_tag,
                         Supplier<hb_tag_t> &tags,
                         Supplier<hb_blob_t *> &blobs,
                         unsigned int table_count)
  {
    TRACE_SERIALIZE (this);
    /* Alloc 12 for the OTHeader. */
    if (unlikely (!c->extend_min (*this))) return_trace (false);
    /* Write sfntVersion (bytes 0..3). */
    sfnt_version.set (sfnt_tag);
    /* Take space for numTables, searchRange, entrySelector, RangeShift
     * and the TableRecords themselves.  */
    if (unlikely (!tables.serialize (c, table_count))) return_trace (false);

    const char *dir_end = (const char *) c->head;
    HBUINT32 *checksum_adjustment = nullptr;

    /* Write OffsetTables, alloc for and write actual table blobs. */
    for (unsigned int i = 0; i < table_count; i++)
    {
      TableRecord &rec = tables.arrayZ[i];
      hb_blob_t *blob = blobs[i];
      rec.tag.set (tags[i]);
      rec.length.set (hb_blob_get_length (blob));
      rec.offset.serialize (c, this);

      /* Allocate room for the table and copy it. */
      char *start = (char *) c->allocate_size<void> (rec.length);
      if (unlikely (!start)) {return false;}

      memcpy (start, hb_blob_get_data (blob, nullptr), rec.length);

      /* 4-byte alignment. */
      c->align (4);
      const char *end = (const char *) c->head;

      if (tags[i] == HB_OT_TAG_head && end - start >= head::static_size)
      {
        head *h = (head *) start;
        checksum_adjustment = &h->checkSumAdjustment;
        checksum_adjustment->set (0);
      }

      rec.checkSum.set_for_data (start, end - start);
    }
    tags += table_count;
    blobs += table_count;

    tables.qsort ();

    if (checksum_adjustment)
    {
      CheckSum checksum;

      /* The following line is a slower version of the following block. */
      //checksum.set_for_data (this, (const char *) c->head - (const char *) this);
      checksum.set_for_data (this, dir_end - (const char *) this);
      for (unsigned int i = 0; i < table_count; i++)
      {
        TableRecord &rec = tables.arrayZ[i];
        checksum.set (checksum + rec.checkSum);
      }

      checksum_adjustment->set (0xB1B0AFBAu - checksum);
    }

    return_trace (true);
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) && tables.sanitize (c));
  }

  protected:
  Tag           sfnt_version;   /* '\0\001\0\00' if TrueType / 'OTTO' if CFF */
  BinSearchArrayOf<TableRecord>
                tables;
  public:
  DEFINE_SIZE_ARRAY (12, tables);
} OpenTypeFontFace;


/*
 * TrueType Collections
 */

struct TTCHeaderVersion1
{
  friend struct TTCHeader;

  inline unsigned int get_face_count (void) const { return table.len; }
  inline const OpenTypeFontFace& get_face (unsigned int i) const { return this+table[i]; }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (table.sanitize (c, this));
  }

  protected:
  Tag           ttcTag;         /* TrueType Collection ID string: 'ttcf' */
  FixedVersion<>version;        /* Version of the TTC Header (1.0),
                                 * 0x00010000u */
  LArrayOf<LOffsetTo<OffsetTable> >
                table;          /* Array of offsets to the OffsetTable for each font
                                 * from the beginning of the file */
  public:
  DEFINE_SIZE_ARRAY (12, table);
};

struct TTCHeader
{
  friend struct OpenTypeFontFile;

  private:

  inline unsigned int get_face_count (void) const
  {
    switch (u.header.version.major) {
    case 2: /* version 2 is compatible with version 1 */
    case 1: return u.version1.get_face_count ();
    default:return 0;
    }
  }
  inline const OpenTypeFontFace& get_face (unsigned int i) const
  {
    switch (u.header.version.major) {
    case 2: /* version 2 is compatible with version 1 */
    case 1: return u.version1.get_face (i);
    default:return Null(OpenTypeFontFace);
    }
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    if (unlikely (!u.header.version.sanitize (c))) return_trace (false);
    switch (u.header.version.major) {
    case 2: /* version 2 is compatible with version 1 */
    case 1: return_trace (u.version1.sanitize (c));
    default:return_trace (true);
    }
  }

  protected:
  union {
  struct {
  Tag           ttcTag;         /* TrueType Collection ID string: 'ttcf' */
  FixedVersion<>version;        /* Version of the TTC Header (1.0 or 2.0),
                                 * 0x00010000u or 0x00020000u */
  }                     header;
  TTCHeaderVersion1     version1;
  } u;
};

/*
 * Mac Resource Fork
 *
 * http://mirror.informatimago.com/next/developer.apple.com/documentation/mac/MoreToolbox/MoreToolbox-99.html
 */

struct ResourceRecord
{
  inline const OpenTypeFontFace & get_face (const void *data_base) const
  { return CastR<OpenTypeFontFace> ((data_base+offset).arrayZ); }

  inline bool sanitize (hb_sanitize_context_t *c,
                        const void *data_base) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) &&
                  offset.sanitize (c, data_base) &&
                  get_face (data_base).sanitize (c));
  }

  protected:
  HBUINT16      id;             /* Resource ID. */
  HBINT16       nameOffset;     /* Offset from beginning of resource name list
                                 * to resource name, -1 means there is none. */
  HBUINT8       attrs;          /* Resource attributes */
  OffsetTo<LArrayOf<HBUINT8>, HBUINT24, false>
                offset;         /* Offset from beginning of data block to
                                 * data for this resource */
  HBUINT32      reserved;       /* Reserved for handle to resource */
  public:
  DEFINE_SIZE_STATIC (12);
};

#define HB_TAG_sfnt HB_TAG ('s','f','n','t')

struct ResourceTypeRecord
{
  inline unsigned int get_resource_count (void) const
  { return tag == HB_TAG_sfnt ? resCountM1 + 1 : 0; }

  inline bool is_sfnt (void) const { return tag == HB_TAG_sfnt; }

  inline const ResourceRecord& get_resource_record (unsigned int i,
                                                    const void *type_base) const
  {
    return (type_base+resourcesZ).as_array (get_resource_count ())[i];
  }

  inline bool sanitize (hb_sanitize_context_t *c,
                        const void *type_base,
                        const void *data_base) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) &&
                  resourcesZ.sanitize (c, type_base,
                                       get_resource_count (),
                                       data_base));
  }

  protected:
  Tag           tag;            /* Resource type. */
  HBUINT16      resCountM1;     /* Number of resources minus 1. */
  OffsetTo<UnsizedArrayOf<ResourceRecord>, HBUINT16, false>
                resourcesZ;     /* Offset from beginning of resource type list
                                 * to reference item list for this type. */
  public:
  DEFINE_SIZE_STATIC (8);
};

struct ResourceMap
{
  inline unsigned int get_face_count (void) const
  {
    unsigned int count = get_type_count ();
    for (unsigned int i = 0; i < count; i++)
    {
      const ResourceTypeRecord& type = get_type_record (i);
      if (type.is_sfnt ())
        return type.get_resource_count ();
    }
    return 0;
  }

  inline const OpenTypeFontFace& get_face (unsigned int idx,
                                           const void *data_base) const
  {
    unsigned int count = get_type_count ();
    for (unsigned int i = 0; i < count; i++)
    {
      const ResourceTypeRecord& type = get_type_record (i);
      /* The check for idx < count is here because ResourceRecord is NOT null-safe.
       * Because an offset of 0 there does NOT mean null. */
      if (type.is_sfnt () && idx < type.get_resource_count ())
        return type.get_resource_record (idx, &(this+typeList)).get_face (data_base);
    }
    return Null (OpenTypeFontFace);
  }

  inline bool sanitize (hb_sanitize_context_t *c, const void *data_base) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) &&
                  typeList.sanitize (c, this,
                                     &(this+typeList),
                                     data_base));
  }

  private:
  inline unsigned int get_type_count (void) const { return (this+typeList).lenM1 + 1; }

  inline const ResourceTypeRecord& get_type_record (unsigned int i) const
  { return (this+typeList)[i]; }

  protected:
  HBUINT8       reserved0[16];  /* Reserved for copy of resource header */
  HBUINT32      reserved1;      /* Reserved for handle to next resource map */
  HBUINT16      resreved2;      /* Reserved for file reference number */
  HBUINT16      attrs;          /* Resource fork attribute */
  OffsetTo<ArrayOfM1<ResourceTypeRecord>, HBUINT16, false>
                typeList;       /* Offset from beginning of map to
                                 * resource type list */
  Offset16      nameList;       /* Offset from beginning of map to
                                 * resource name list */
  public:
  DEFINE_SIZE_STATIC (28);
};

struct ResourceForkHeader
{
  inline unsigned int get_face_count (void) const
  { return (this+map).get_face_count (); }

  inline const OpenTypeFontFace& get_face (unsigned int idx,
                                           unsigned int *base_offset = nullptr) const
  {
    const OpenTypeFontFace &face = (this+map).get_face (idx, &(this+data));
    if (base_offset)
      *base_offset = (const char *) &face - (const char *) this;
    return face;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) &&
                  data.sanitize (c, this, dataLen) &&
                  map.sanitize (c, this, &(this+data)));
  }

  protected:
  LOffsetTo<UnsizedArrayOf<HBUINT8>, false>
                data;           /* Offset from beginning of resource fork
                                 * to resource data */
  LOffsetTo<ResourceMap, false>
                map;            /* Offset from beginning of resource fork
                                 * to resource map */
  HBUINT32      dataLen;        /* Length of resource data */
  HBUINT32      mapLen;         /* Length of resource map */
  public:
  DEFINE_SIZE_STATIC (16);
};

/*
 * OpenType Font File
 */

struct OpenTypeFontFile
{
  enum {
    CFFTag              = HB_TAG ('O','T','T','O'), /* OpenType with Postscript outlines */
    TrueTypeTag         = HB_TAG ( 0 , 1 , 0 , 0 ), /* OpenType with TrueType outlines */
    TTCTag              = HB_TAG ('t','t','c','f'), /* TrueType Collection */
    DFontTag            = HB_TAG ( 0 , 0 , 1 , 0 ), /* DFont Mac Resource Fork */
    TrueTag             = HB_TAG ('t','r','u','e'), /* Obsolete Apple TrueType */
    Typ1Tag             = HB_TAG ('t','y','p','1')  /* Obsolete Apple Type1 font in SFNT container */
  };

  inline hb_tag_t get_tag (void) const { return u.tag; }

  inline unsigned int get_face_count (void) const
  {
    switch (u.tag) {
    case CFFTag:        /* All the non-collection tags */
    case TrueTag:
    case Typ1Tag:
    case TrueTypeTag:   return 1;
    case TTCTag:        return u.ttcHeader.get_face_count ();
    case DFontTag:      return u.rfHeader.get_face_count ();
    default:            return 0;
    }
  }
  inline const OpenTypeFontFace& get_face (unsigned int i, unsigned int *base_offset = nullptr) const
  {
    if (base_offset)
      *base_offset = 0;
    switch (u.tag) {
    /* Note: for non-collection SFNT data we ignore index.  This is because
     * Apple dfont container is a container of SFNT's.  So each SFNT is a
     * non-TTC, but the index is more than zero. */
    case CFFTag:        /* All the non-collection tags */
    case TrueTag:
    case Typ1Tag:
    case TrueTypeTag:   return u.fontFace;
    case TTCTag:        return u.ttcHeader.get_face (i);
    case DFontTag:      return u.rfHeader.get_face (i, base_offset);
    default:            return Null(OpenTypeFontFace);
    }
  }

  inline bool serialize_single (hb_serialize_context_t *c,
                                hb_tag_t sfnt_tag,
                                Supplier<hb_tag_t> &tags,
                                Supplier<hb_blob_t *> &blobs,
                                unsigned int table_count)
  {
    TRACE_SERIALIZE (this);
    assert (sfnt_tag != TTCTag);
    if (unlikely (!c->extend_min (*this))) return_trace (false);
    return_trace (u.fontFace.serialize (c, sfnt_tag, tags, blobs, table_count));
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    if (unlikely (!u.tag.sanitize (c))) return_trace (false);
    switch (u.tag) {
    case CFFTag:        /* All the non-collection tags */
    case TrueTag:
    case Typ1Tag:
    case TrueTypeTag:   return_trace (u.fontFace.sanitize (c));
    case TTCTag:        return_trace (u.ttcHeader.sanitize (c));
    case DFontTag:      return_trace (u.rfHeader.sanitize (c));
    default:            return_trace (true);
    }
  }

  protected:
  union {
  Tag                   tag;            /* 4-byte identifier. */
  OpenTypeFontFace      fontFace;
  TTCHeader             ttcHeader;
  ResourceForkHeader    rfHeader;
  } u;
  public:
  DEFINE_SIZE_UNION (4, tag);
};


} /* namespace OT */


#endif /* HB_OPEN_FILE_HH */

message:
I am thinking...: Let me understand the vulnerability:

1. The crash is in `KerxSubTableFormat1::driver_context_t::transition` when accessing `BEInt<short, 2>::operator short` - this is an MSAN (uninitialized memory read) issue.

2. Looking at the `transition` function in `KerxSubTableFormat1`:
   - `kernAction` is an `OffsetTo<UnsizedArrayOf<FWORD>>` 
   - `kern_idx = Format1EntryT::kernActionIndex(entry)` gets the index from the entry
   - `kern_idx = Types::offsetToIndex(kern_idx, &table->machine, kernAction.arrayZ)` converts it
   - `const FWORD *actions = &kernAction[kern_idx]` - this reads from the offset
   - Then `if (!c->sanitizer.check_array(actions, depth * tuple_count))` checks bounds
   - But the issue is that `kernAction` offset could point to uninitialized data within the font file

3. The key issue: The `kernAction` offset in the kerx format1 subtable points to the kernAction array. If this offset points beyond the actual data in the font file, or if the data at that offset is uninitialized, reading from it would cause MSAN to report an uninitialized read.

4. Actually, looking more carefully at the crash trace: "UNKNOWN READ" with MSAN. This means reading from memory that hasn't been initialized. The `BEInt<short, 2>::operator short` is the conversion operator that reads two bytes from `v[0]` and `v[1]`.

5. The issue is likely that the `kernAction` offset points to a location in the font file that is beyond the actual data provided, so when the bytes are read, they contain uninitialized memory.

6. To create a PoC, I need to craft a minimal TrueType font file with a `kerx` table containing a Format1 subtable where:
   - The state machine has entries that trigger a transition with Push and a kernActionIndex
   - The kernAction offset points to uninitialized/out-of-bounds data
   - The font needs enough structure to pass initial sanitization checks

Let me look at the sanitization more carefully. In `sanitize()` for Format1:
```cpp
return_trace (likely (c->check_struct (this) &&
                      machine.sanitize (c)));
```
It only checks the struct and the machine (state table). The kernAction offset is NOT validated during sanitize - it says "The rest of array sanitizations are done at run-time."

So the vulnerability is: the `kernAction` offset can point to arbitrary data, and when the state machine processes a transition with a valid `kernActionIndex`, it reads from that offset without proper bounds checking at sanitize time. The runtime check `c->sanitizer.check_array(actions, depth * tuple_count)` does check, but if the offset itself points to uninitialized memory (beyond the font data), the BEInt read still triggers MSAN.

Wait, actually the `check_array` should catch out-of-bounds reads. Let me re-read the code...

Actually, looking at the crash state more carefully: "BEInt<short, 2>::operator short" - this is the conversion from BEInt to short. The `FWORD` type is `BEInt<short, 2>`. So when we do `int v = *actions;`, it calls `BEInt<short, 2>::operator short()` which reads `v[0]` and `v[1]`.

The MSAN issue is that the memory at `actions` contains uninitialized bytes. This could happen if:
1. The `kernAction` offset points beyond the font data
2. The `kern_idx` calculation results in an index beyond the array

But `check_array` should prevent this... unless the check is insufficient.

Let me look at `check_array` more carefully.

Actually, I think the issue might be simpler. Let me look at the `kernAction` offset calculation:

```cpp
kern_idx = Format1EntryT::kernActionIndex (entry);
kern_idx = Types::offsetToIndex (kern_idx, &table->machine, kernAction.arrayZ);
const FWORD *actions = &kernAction[kern_idx];
```

For ExtendedTypes (which is what KerxSubTableHeader uses), `offsetToIndex` just returns the offset unchanged. So `kern_idx` is used directly as an index into `kernAction` array.

The `kernAction` is an `OffsetTo<UnsizedArrayOf<FWORD>>`. The offset is from the beginning of the subtable. If this offset is crafted to point to a location that's within the font file but contains uninitialized data (or data beyond what was provided), then reading from it would trigger MSAN.

Actually, I think the simplest approach is: the `kernAction` offset can be set to point to a location that is within the bounds of the font data but contains uninitialized bytes. But since the font data is all provided by the fuzzer input, all bytes are initialized...

Wait, MSAN tracks uninitialized memory at runtime. The font data comes from the fuzzer input which is all initialized. So where does the uninitialized memory come from?

Let me re-read the crash: "UNKNOWN READ" at address `0x7071000000ac`. This looks like a heap address. Maybe the issue is that the offset points to memory that was allocated but not written to?

Actually, looking at the `hb_blob_create` call in the fuzzer: it creates a blob from the data. The blob is read-only. When the font is parsed, various offsets are followed. If an offset goes beyond the blob's data, it would normally be caught by sanitize checks.

But wait - the `kernAction` offset is NOT checked during sanitize. The comment says "The rest of array sanitizations are done at run-time." So during `apply`, when `transition` is called, it reads from `kernAction[kern_idx]` which could be beyond the blob data.

The `check_array` call checks if `actions` to `actions + depth * tuple_count` is within bounds. But if `kernAction` offset itself points beyond the blob, then `&kernAction[kern_idx]` would be an out-of-bounds pointer, and even though `check_array` would fail and return false, the mere act of computing `&kernAction[kern_idx]` might not crash... but the `*actions` dereference happens before `check_array`? No, let me re-read:

```cpp
kern_idx = Format1EntryT::kernActionIndex (entry);
kern_idx = Types::offsetToIndex (kern_idx, &table->machine, kernAction.arrayZ);
const FWORD *actions = &kernAction[kern_idx];
if (!c->sanitizer.check_array (actions, depth * tuple_count))
{
    depth = 0;
    return false;
}
```

The `&kernAction[kern_idx]` computes a pointer but doesn't dereference it. Then `check_array` checks if the range is valid. If it's not valid, it returns false without reading. So the read shouldn't happen...

Unless `check_array` itself reads the memory? Let me check what `check_array` does.

Actually, I think the issue might be different. Let me look at the `kernAction` offset resolution. `kernAction` is declared as:
```cpp
OffsetTo<UnsizedArrayOf<FWORD>, HBUINT, false> kernAction;
```

When we do `kernAction[kern_idx]`, this calls `UnsizedArrayOf<FWORD>::operator[]` which likely does pointer arithmetic on `this + offset + kern_idx * sizeof(FWORD)`.

The `kernAction` offset is from the beginning of the subtable. If this offset is very large, it could point beyond the blob. The `check_array` should catch this...

Let me look at the actual UnsizedArrayOf and check_array implementations.

Actually, I think I need to just build the PoC. The key insight from the crash report is that it's a Format1 kerx subtable with a state machine. The crash is an UNKNOWN READ (MSAN), meaning uninitialized memory is being read. 

Let me think about what could cause uninitialized memory reads in this context. The font data comes from the fuzzer input, so all bytes are initialized. But the `kernAction` offset could point to a location that, while within the blob, contains data that when interpreted as FWORD values and then used in tuple-aware kerning, reads beyond the initialized data.

Wait, I think I found it! Look at `kerxTupleKern`:
```cpp
static inline int
kerxTupleKern (int value,
               unsigned int tupleCount,
               const void *base,
               hb_aat_apply_context_t *c)
{
  if (likely (!tupleCount)) return value;
  unsigned int offset = value;
  const FWORD *pv = &StructAtOffset<FWORD> (base, offset);
  if (unlikely (!c->sanitizer.check_array (pv, tupleCount))) return 0;
  return *pv;
}
```

This is called from `transition` indirectly? No, it's not called from transition in Format1. Let me re-read the transition code...

In the transition function, the kernAction values are read directly:
```cpp
const FWORD *actions = &kernAction[kern_idx];
if (!c->sanitizer.check_array (actions, depth * tuple_count))
{
    depth = 0;
    return false;
}
...
int v = *actions;
actions += tuple_count;
```

So the values are read from the kernAction array. The `check_array` checks that `depth * tuple_count` entries are valid. But what if `depth` is 0? Then `check_array` checks 0 entries, which always passes. Then the while loop `while (!last && depth--)` doesn't execute because depth is 0. So no read happens.

But what if depth > 0 and the check passes? Then the values are read. The values are FWORD (signed 16-bit big-endian). If the values are uninitialized, MSAN would catch it.

